import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { isValidDate, addDays, lastDayOfMonth } from './dates.js';

function validateDiscount(discountPercent) {
  if (discountPercent === undefined) return ok(0);
  if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
    return fail('DISCOUNT_INVALID');
  }
  return ok(discountPercent);
}

function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') return addDays(issueDate, 14);
  if (terms === 'NET30') return addDays(issueDate, 30);
  if (terms === 'EOM') return lastDayOfMonth(issueDate);
  return null;
}

export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

export function discountAmount(line) {
  const discount = line.discountPercent ?? 0;
  return Math.round(lineTotal(line) * discount / 100);
}

export function lineVAT(line) {
  const discountedAmount = lineTotal(line) - discountAmount(line);
  return Math.round(discountedAmount * line.vatRate / 100);
}

export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + discountAmount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVAT(line), 0);
  const voucher = invoice.voucher?.amount ?? 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);
  return { subtotal, discount, vat, voucher, total };
}

export function applyVoucher(invoice, { code, amount }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
  if (invoice.voucher) return fail('VOUCHER_EXISTS');
  if (!Number.isInteger(amount) || amount <= 0) return fail('AMOUNT_INVALID');

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    terms: invoice.terms,
    dueDate: invoice.dueDate,
    status: invoice.status,
    lines: invoice.lines.map((line) => ({ ...line })),
    voucher: { code, amount },
  });
}

export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;
  const hasExplicitDiscount = discountPercent !== undefined;
  const discountToValidate = hasExplicitDiscount ? discountPercent : TIER_DISCOUNTS[customer.tier] ?? 0;
  const discountResult = validateDiscount(discountToValidate);
  if (!discountResult.ok) return discountResult;

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const existingLineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  const newLines = invoice.lines.map((line) => ({ ...line }));

  if (existingLineIndex !== -1) {
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    const newLine = {
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };
    if (discountResult.value > 0) {
      newLine.discountPercent = discountResult.value;
    }
    newLines.push(newLine);
  }

  const result = {
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    terms: invoice.terms,
    dueDate: invoice.dueDate,
    status: invoice.status,
    lines: newLines,
  };
  if (invoice.voucher) {
    result.voucher = { ...invoice.voucher };
  }
  return ok(result);
}

export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((_, index) => index !== lineIndex);

  const result = {
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    terms: invoice.terms,
    dueDate: invoice.dueDate,
    status: invoice.status,
    lines: newLines,
  };
  if (invoice.voucher) {
    result.voucher = { ...invoice.voucher };
  }
  return ok(result);
}

export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;

  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  const dueDate = calculateDueDate(issueDate, terms);
  if (dueDate === null) return fail('TERMS_INVALID');

  if (!lines || lines.length === 0) return fail('NO_LINES');

  const enrichedLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    const hasExplicitDiscount = line.discountPercent !== undefined;
    const discountToValidate = hasExplicitDiscount ? line.discountPercent : TIER_DISCOUNTS[customer.tier] ?? 0;
    const discountResult = validateDiscount(discountToValidate);
    if (!discountResult.ok) return discountResult;

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    const newLine = {
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };
    if (discountResult.value > 0) {
      newLine.discountPercent = discountResult.value;
    }
    enrichedLines.push(newLine);
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    terms,
    dueDate,
    status: 'draft',
    lines: enrichedLines,
  });
}

export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  const result = {
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    terms: invoice.terms,
    dueDate: invoice.dueDate,
    status: 'issued',
    number,
    lines: invoice.lines.map((line) => ({ ...line })),
  };
  if (invoice.voucher) {
    result.voucher = { ...invoice.voucher };
  }
  return ok(result);
}

