test('discountAmount calculates discount correctly', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 9500,
    vatRate: 21,
    discountPercent: 10,
  };
  // lineTotal = 10 * 9500 = 95000, discount = 95000 * 10 / 100 = 9500
  assert.equal(discountAmount(line), 9500);
});

test('discountAmount with no discount returns 0', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 9500,
    vatRate: 21,
  };
  assert.equal(discountAmount(line), 0);
});

test('discountAmount rounds to nearest cent', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 100,
    vatRate: 21,
    discountPercent: 33.33,
  };
  // lineTotal = 10 * 100 = 1000, discount = 1000 * 33.33 / 100 = 333.3 -> 333
  assert.equal(discountAmount(line), 333);
});

test('invoiceTotals returns discount field', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });
  const totals = invoiceTotals(r.value);
  assert.ok('discount' in totals);
  assert.equal(totals.discount, 9500);
});

test('invoiceTotals with single line and discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });
  const totals = invoiceTotals(r.value);
  // subtotal = 95000, discount = 9500, discounted = 85500
  // VAT = 85500 * 21 / 100 = 17955
  // Total = 95000 - 9500 + 17955 = 103455
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 9500);
  assert.equal(totals.vat, 17955);
  assert.equal(totals.total, 103455);
});

test('invoiceTotals with multiple lines and different discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 20 },
    ],
  });
  const totals = invoiceTotals(r.value);
  // DEV-HOUR: lineTotal = 95000, discount = 9500, discounted = 85500, VAT 21% = 17955
  // LOGO-PACK: lineTotal = 120000, discount = 24000, discounted = 96000, VAT 21% = 20160
  // subtotal = 215000, discount = 33500, vat = 38115, total = 219615
  assert.equal(totals.subtotal, 215000);
  assert.equal(totals.discount, 33500);
  assert.equal(totals.vat, 38115);
  assert.equal(totals.total, 219615);
});

test('invoiceTotals with mix of discounted and non-discounted lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  const totals = invoiceTotals(r.value);
  // DEV-HOUR: lineTotal = 95000, explicit discount 10% = 9500, discounted = 85500, VAT 21% = 17955
  // LOGO-PACK: lineTotal = 120000, gets gold tier discount 5% = 6000, discounted = 114000, VAT 21% = 23940
  // subtotal = 215000, discount = 15500, vat = 41895, total = 241395
  assert.equal(totals.subtotal, 215000);
  assert.equal(totals.discount, 15500);
  assert.equal(totals.vat, 41895);
  assert.equal(totals.total, 241395);
});

test('invoiceTotals clamps total to zero when discount exceeds subtotal', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'draft',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 100,
        vatRate: 21,
        discountPercent: 100,
      },
    ],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 100, discount = 100, total should be 0, not -0
  assert.equal(totals.subtotal, 100);
  assert.equal(totals.discount, 100);
  assert.equal(totals.total, 0);
});

test('addLine with discount', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const r2 = addLine(r1.value, { sku: 'LOGO-PACK', qty: 1, discountPercent: 15 });
