import test from 'node:test';
import assert from 'node:assert/strict';
import { lineTotal, discountAmount, lineVAT, invoiceTotals } from '../src/totals.js';
import { createInvoice, applyVoucher } from '../src/invoices.js';

test('lineTotal multiplies qty by unitPrice', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 9500,
    vatRate: 21,
  };
  assert.equal(lineTotal(line), 95000);
});

test('lineTotal with qty of 1', () => {
  const line = {
    sku: 'LOGO-PACK',
    name: 'Logo package',
    qty: 1,
    unitPrice: 120000,
    vatRate: 21,
  };
  assert.equal(lineTotal(line), 120000);
});

test('discountAmount calculates discount correctly', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 9500,
    vatRate: 21,
    discountPercent: 10,
  };
  assert.equal(discountAmount(line), 9500);
});

test('discountAmount with no discount returns 0', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 9500,
    vatRate: 21,
  };
  assert.equal(discountAmount(line), 0);
});

test('discountAmount rounds to nearest cent', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 100,
    vatRate: 21,
    discountPercent: 33.33,
  };
  assert.equal(discountAmount(line), 333);
});

test('lineVAT calculates VAT on line after discount', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 9500,
    vatRate: 21,
    discountPercent: 10,
  };
  assert.equal(lineVAT(line), 17955);
});

test('lineVAT with no discount', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 9500,
    vatRate: 21,
  };
  assert.equal(lineVAT(line), 19950);
});

test('lineVAT with 0% VAT rate', () => {
  const line = {
    sku: 'WORKSHOP-DAY',
    name: 'Workshop (day)',
    qty: 1,
    unitPrice: 50000,
    vatRate: 0,
  };
  assert.equal(lineVAT(line), 0);
});

test('lineVAT with 9% VAT rate', () => {
  const line = {
    sku: 'PRINT-A4',
    name: 'Printed flyer A4 (each)',
    qty: 100,
    unitPrice: 37,
    vatRate: 9,
  };
  assert.equal(lineVAT(line), 333);
});

test('lineVAT rounds to nearest cent', () => {
  const line = {
    sku: 'STICKER',
    name: 'Sticker',
    qty: 100,
    unitPrice: 100,
    vatRate: 21,
